/**
 * src/main.tsx: the entry point.
 *
 * Opens the store (storage is read into memory first, so the first render
 * already has the user's tasks), registers the service worker in the built
 * app (offline and install, public/sw.js is generated by the build), then
 * renders the app. Any failure shows the crash screen (app/Crash.tsx).
 */
import { StrictMode } from 'react';
import { createRoot } from 'react-dom/client';

import { App } from './app/App';
import { CrashBoundary, CrashScreen } from './app/Crash';
import { startStore } from './store';
import { StoreProvider } from './store/react';
import './styles/theme.css';
import './styles/app.css';

// Registered first, so an update can still arrive even if this version fails to start.
if (import.meta.env.PROD && 'serviceWorker' in navigator) {
  void navigator.serviceWorker.register(`${import.meta.env.BASE_URL}sw.js`).catch(() => undefined);
}

const root = createRoot(document.getElementById('root')!);
try {
  const bundle = await startStore();
  root.render(
    <StrictMode>
      <StoreProvider value={bundle}>
        <CrashBoundary bundle={bundle}>
          <App />
        </CrashBoundary>
      </StoreProvider>
    </StrictMode>,
  );
} catch (error) {
  // The store couldn't start: say so (never a blank page).
  root.render(<CrashScreen error={error} />);
}
